import sys

def max_length_of_journey(s):
    n = len(s)
    dp = [0] * (n + 1)

    for i in range(n, 0, -1):
        for j in range(i + 1, n + 1):
            if s[i-1] == s[j-1]:
                dp[i] = max(dp[i], dp[j] + 1)

    return dp[1]

